"""Regenerate internal/pycompat/unicode.txt and testdata/fixtures.json from this Python.

Run from the repository root: python3 -I internal/pycompat/testdata/gen.py

unicode.txt holds the per-code-point str predicates the Go package cannot take from its own
stdlib tables (a different Unicode version may ship with Go). Each line is a record kind and
space-separated hex ranges lo-hi:
  A str.isalpha   D str.isdecimal   G str.isdigit   N str.isnumeric
  P str.isprintable   S str.isspace
isalnum is A|D|G|N and re's \\w on str patterns is isalnum or '_' (checked by a digest).
The case records are CPython's per-character flags, probed through the str methods:
  U upper (ch.isupper())   L lower (ch.islower())
  T title or both upper and lower (neither ch+"A" isupper nor ch+"a" islower)
  C cased (ch+"a").title() keeps the "a"   I case-ignorable (the final-sigma probe)
and the full mappings cp:cp.cp... of the single character where they differ:
  u ch.upper()   t ch.title()
str.lower() is internal/textfold's Lower.

fixtures.json holds the outputs of the real Python operations the Go functions reproduce,
one case per line, plus SHA-256 digests over every non-surrogate code point. Typed values
are [kind, value] pairs: none, bool, int (decimal text), float (IEEE bits as hex), str,
list (of typed values), tuple (of typed values).
"""
import hashlib
import html
import json
import math
import os
import posixpath
import random
import re
import struct
import sys
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.dirname(HERE)


def chars():
    return (chr(c) for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF)


def ranges(pred):
    out, start, prev = [], None, None
    for ch in chars():
        c = ord(ch)
        if pred(ch):
            if start is None or c != prev + 1:
                if start is not None:
                    out.append((start, prev))
                start = c
            prev = c
    if start is not None:
        out.append((start, prev))
    return out


def pack(kind, entries, width=200):
    lines, cur = [], kind
    for e in entries:
        if len(cur) + 1 + len(e) > width and cur != kind:
            lines.append(cur)
            cur = kind
        cur += " " + e
    if cur != kind:
        lines.append(cur)
    return lines


PREDICATES = {"A": str.isalpha, "D": str.isdecimal, "G": str.isdigit, "N": str.isnumeric,
              "P": str.isprintable, "S": str.isspace}


SIGMA, FINAL = "\u03a3", "\u03c2"
CASE = {"U": str.isupper, "L": str.islower,
        "T": lambda ch: not (ch + "A").isupper() and not (ch + "a").islower(),
        "C": lambda ch: (ch + "a").title()[-1] == "a",
        "I": lambda ch: ("A" + ch + SIGMA).lower()[-1] == FINAL and (ch + SIGMA).lower()[-1] != FINAL}
MAPS = {"u": str.upper, "t": str.title}


def seq(s):
    return ".".join("%04X" % ord(c) for c in s)


def write_unicode():
    lines = ["# generated by internal/pycompat/testdata/gen.py: Python %s, Unicode %s; do not edit"
             % (sys.version.split()[0], unicodedata.unidata_version)]
    for kind, pred in list(PREDICATES.items()) + list(CASE.items()):
        lines += pack(kind, ["%04X-%04X" % r for r in ranges(pred)])
    for kind, fn in MAPS.items():
        lines += pack(kind, ["%04X:%s" % (ord(ch), seq(fn(ch))) for ch in chars() if fn(ch) != ch])
    with open(os.path.join(PKG, "unicode.txt"), "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")


def digest(parts):
    h = hashlib.sha256()
    for p in parts:
        h.update(p.encode("utf-8"))
        h.update(b"\n")
    return h.hexdigest()


def bits(f):
    return "%016x" % struct.unpack(">Q", struct.pack(">d", f))[0]


def typed(v):
    if v is None:
        return ["none"]
    if isinstance(v, bool):
        return ["bool", v]
    if isinstance(v, int):
        return ["int", str(v)]
    if isinstance(v, float):
        return ["float", bits(v)]
    if isinstance(v, str):
        return ["str", v]
    if isinstance(v, list):
        return ["list", [typed(x) for x in v]]
    if isinstance(v, tuple):
        return ["tuple", [typed(x) for x in v]]
    raise TypeError(v)


def attempt(f, *a):
    try:
        return f(*a)
    except (ValueError, TypeError, KeyError, OverflowError):
        return None


STRINGS = ["", "a", "it's", 'say "hi"', "both ' \"", "back\\slash", "tab\tnl\nnr\r", "\x00\x1f\x7f",
           "\x80\x9f\xa0\xad\xff", "é€😀", "\u200b\u2028\U000e0001\ufeff", "\ud7ff\ue000\uffff", "Ω≈ç√"]
FLOATS = [0.0, -0.0, 1.0, -1.0, 0.5, 0.1, 1 / 3, 2 / 3, 100.0, 1e15, 1e16, 9999999999999998.0, 1e-4,
          1e-5, 1.5e-5, 123456789.125, 1e22, 1e300, 5e-324, 2.2250738585072014e-308, 1.7976931348623157e308,
          float("inf"), float("-inf"), float("nan"), 0.000123, 123456.0, 1234567.0, 0.00001234, 1e6, 999999.5]
INT_TEXTS = ["0", "-0", "+7", " 1_000 ", "\t42\n", "٣٤", "１２", "-9223372036854775808", "9223372036854775807",
             "9223372036854775808", "99999999999999999999", "1__0", "_1", "1_", "", " ", "0x10", "1.0", "1e3",
             "+", "-", "--1", "007", "\u00a01\u2003", "1 2", "𝟏𝟐"]
FLOAT_TEXTS = ["1e3", " -.5 ", "inf", "-Infinity", "+iNf", "nan", "-NaN", "1_0.5", "1_e3", "0x1p3", "1e400",
               "-1e400", ".", "e5", "1.", ".5", "5e-324", "2e-324", "1e-400", "0.1", "1_000.000_1", "1__0",
               "\t3.25\n", "", " ", "infinity", "infinit", "nanx", "1e", "1e+", "1E-2", "١٫٥", "1,5", "١٢.٥", "\u00a02\u2003", "１e２"]
PERCENT = [
    ("%(prog)s 1.0", {"prog": "tool"}), ("%(a)s|%(a)r|%(b)d|%(c)d", {"a": "x'y", "b": 3, "c": True}),
    ("%(f)s %(f)r %(f)d", {"f": 2.75}), ("%(n)s %(l)s %(t)s", {"n": None, "l": ["a", 1], "t": ("K", "V")}),
    ("100%% sure %(x)s", {"x": 1}), ("%(missing)s", {}), ("50% off", {}), ("%(x)", {"x": 1}),
    ("%(x)z", {"x": 1}), ("%(s)d", {"s": "text"}), ("trailing %", {}), ("%(", {}), ("plain", {}),
    ("%(k)s and %(k)s", {"k": "é"}), ("%(b)s %(b)r", {"b": False}),
]
DECODE = [b"plain", b"\xff", b"a\xe2\x82b", b"\xed\xa0\x80", b"\xf0\x9f\x98", b"\xc0\xaf", b"\xf4\x90\x80\x80",
          b"\xf8\x88\x80\x80\x80", b"\xe0\x80\xaf", b"\xc3", b"\x80\x80", b"\xf0\x80\x80\x80",
          b"\xf0\x9f\x98\x80\xf0\x9f", "é€😀".encode(), b"\xe2\x82\xac\xe2\x82", b"x\xc2\xc2y", b"\xef\xbf\xbf"]
LINES = ["", "a", "a\n", "a\nb", "a\r\nb", "a\rb", "a\n\rb", "a\r\n\r\nb", "\n", "\r\n", "\r", "x\x0by\x0cz",
         "a\x1cb\x1dc\x1ed\x1fe", "a\x85b\u2028c\u2029d", "trailing\r\n", "\r\r\n\n", "é\r\nñ"]
SPACES = ["", "  a  b  ", "\t\na\x0b\x0cb\r", "\x1ca\x1db\x1e\x1f", "\xa0a\u2003b\u3000", "a\u200bb", "\x85x\u2028",
          "no-space", "\ufeffa",
          "b=baja\x1cc=control\u00a0 d=x\x1f"]
HTML = ["", "a<b>&\"c'", "&amp;&lt;&gt;&quot;&#39;&#x27;", "&notit; &notin; &not", "&#0; &#65; &#x41; &#X41;",
        "&#128; &#x80; &#x9f; &#150;", "&#xd800; &#x110000; &#1114112;", "&#1; &#x7f; &#xfdd0; &#xfffe;",
        "&#13; &#x0d;", "&amp &lt3 &copy;2026", "&unknown; & ; &#; &#x;", "&AElig &aelig;", "plain"]
PATHS = ["", "a", "/a/b.txt", "a/b/", "dir/.hidden", "dir/..dots", "x.tar.gz", "/a.b/c", "./x.", "a/b.c/d",
         "...", ".a.b"]
CASES = ["", "a", "A", "1", "Hello World", "hello world", "HELLO", "Hello", "hELLO", "123", "123abc", "ABC123",
         "a1B2", "\u01c5ungla", "\u01c5", "\u01c8ubljana \u01ca", "\u00df stra\u00dfe", "\u0149", "\ufb01le \ufb02ow",
         "\u0130stanbul", "\u03a3\u0391\u03a3 \u03a3\u0391\u03a3.", "\u038c\u03a3\u039f\u03a3", "a\u03a3", "\u03a3",
         "a\u03a3b", "a\u03a3'", "a'\u03a3", "A\u0345\u03a3", "\u02b0ello", "\u1fb3 \u1fbc", "e\u0301COLE",
         "they're bill's friends", "hello_world-foo bar", "\u00dcn\u00efc\u00f6d\u00e9 \u00c0\u00c9\u00ce\u00d5\u00dc",
         "\u2177 \u2167", "\u24d0\u24b6", "\U00010428\U00010400", "\u65e5\u672c\u8a9e", "ABC def",
         "Mr. Smith's CAT", "  leading", "\u0345", "A\u0345", "\u01c5A", "\u01c5a", "a\u01c5"]
JUST = ["", "a", "ab", "abc", "h\u00e9llo", "\u65e5\u672c", "e\u0301", "\U0001f600"]
FILLS = [" ", "*", "\u00e9", "\u65e5"]
WIDTHS = [-1, 0, 1, 2, 3, 4, 5, 6, 7, 10]
CUTS = ["", "a", "abc", "h\u00e9llo w\u00f6rld", "e\u0301\U0001f600x", "\u65e5\u672c\u8a9e\u30c6\u30ad\u30b9\u30c8"]
JOINS = [["a", "b"], ["a/", "b"], ["a", "/b", "c"], ["", "a"], ["a", ""], ["/", "x"], ["a", "b/", "c"]]


def case_context(ch):
    """The multi-character paths of the case methods around ch, joined with '|'."""
    flags = "%d%d%d%d" % ((ch + "A").isupper(), (ch + "a").islower(), (ch + "ab").istitle(), ("A" + ch).istitle())
    return "|".join([flags, ("a" + ch + "b").title(), ("A" + ch + SIGMA).swapcase(), ("x" + ch).capitalize(),
                     (ch + SIGMA + "a").title(), ("A" + SIGMA + ch).capitalize()])


def float_samples():
    rnd = random.Random(20261017)
    out = list(FLOATS)
    for _ in range(400):
        out.append(struct.unpack(">d", struct.pack(">Q", rnd.getrandbits(64)))[0])
    for _ in range(200):
        out.append(round(rnd.uniform(-1e6, 1e6), rnd.randint(0, 6)))
    return out


def main():
    sys.dont_write_bytecode = True
    write_unicode()
    word = re.compile(r"\w")
    floats = float_samples()
    out = {
        "python": sys.version.split()[0],
        "unicode": unicodedata.unidata_version,
        "repr": [[typed(v), repr(v), str(v)] for v in STRINGS + FLOATS[:8] +
                 [None, True, False, 0, -12, 10 ** 20, ["a", 1, None, 2.5], ("one",), ("K", "V"), (), []]],
        "float": [[bits(f), repr(f), "%g" % f, json.dumps(f), attempt(lambda x: str(int(x)), f)] for f in floats],
        "parse_int": [[s, attempt(lambda x: str(int(x)), s)] for s in INT_TEXTS],
        "parse_float": [[s, attempt(lambda x: bits(float(x)), s)] for s in FLOAT_TEXTS],
        "percent": [[fmt, {k: typed(v) for k, v in params.items()}, attempt(lambda: fmt % params)]
                    for fmt, params in PERCENT],
        "decode": [[b.hex(), b.decode("utf-8", "replace")] for b in DECODE],
        "lines": [[s, s.splitlines(), s.splitlines(True)] for s in LINES],
        "spaces": [[s, s.strip(), s.split()] for s in SPACES],
        "html": [[s, html.escape(s), html.unescape(s)] for s in HTML],
        "paths": [[p, posixpath.basename(p), posixpath.splitext(p)[0]] for p in PATHS],
        "joins": [[parts, posixpath.join(*parts)] for parts in JOINS],
        "case": [[c, c.isupper(), c.islower(), c.istitle(), c.upper(), c.lower(), c.title(), c.capitalize(),
                  c.swapcase()] for c in CASES],
        "just": [[s, f, [[s.ljust(w, f), s.rjust(w, f), s.center(w, f)] for w in WIDTHS]]
                 for s in JUST for f in FILLS],
        "cut": [[s, [s[:n] for n in range(-8, 9)]] for s in CUTS],
        "digests": {
            "alpha": digest(ch for ch in chars() if ch.isalpha()),
            "decimal": digest(ch for ch in chars() if ch.isdecimal()),
            "digit": digest(ch for ch in chars() if ch.isdigit()),
            "numeric": digest(ch for ch in chars() if ch.isnumeric()),
            "alnum": digest(ch for ch in chars() if ch.isalnum()),
            "printable": digest(ch for ch in chars() if ch.isprintable()),
            "space": digest(ch for ch in chars() if ch.isspace()),
            "word": digest(ch for ch in chars() if word.match(ch)),
            "linebreak": digest(ch for ch in chars() if len(("a" + ch + "b").splitlines()) == 2),
            "repr": digest(repr(ch) for ch in chars()),
            "decimal_value": digest(ch + str(int(ch)) for ch in chars() if ch.isdecimal()),
            "isupper": digest(ch for ch in chars() if ch.isupper()),
            "islower": digest(ch for ch in chars() if ch.islower()),
            "istitle": digest(ch for ch in chars() if ch.istitle()),
            "upper": digest(ch.upper() for ch in chars()),
            "title": digest(ch.title() for ch in chars()),
            "capitalize": digest(ch.capitalize() for ch in chars()),
            "swapcase": digest(ch.swapcase() for ch in chars()),
            "case_context": digest(case_context(ch) for ch in chars()),
        },
    }
    with open(os.path.join(HERE, "fixtures.json"), "w", encoding="utf-8") as fh:
        fh.write("{\n")
        keys = list(out)
        for i, k in enumerate(keys):
            v = out[k]
            sep = "," if i < len(keys) - 1 else ""
            if isinstance(v, list):
                fh.write(" %s: [\n" % json.dumps(k))
                fh.write(",\n".join("  " + json.dumps(row, ensure_ascii=False) for row in v))
                fh.write("\n ]%s\n" % sep)
            else:
                fh.write(" %s: %s%s\n" % (json.dumps(k), json.dumps(v, ensure_ascii=False, sort_keys=True), sep))
        fh.write("}\n")
    print("unicode.txt and fixtures.json written", file=sys.stderr)


if __name__ == "__main__":
    main()
